CREATE OR REPLACE FUNCTION erp_private.ecommerce_stock_omnicanal(p_producto_ids uuid[] DEFAULT NULL::uuid[], p_ubicacion_destino_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare resultado jsonb; locales jsonb; limite numeric:=100; admite_traslados boolean:=true;
begin
  if p_producto_ids is not null and cardinality(p_producto_ids)>1000 then raise exception 'Consulta como máximo 1000 productos por solicitud'; end if;
  if p_ubicacion_destino_id is not null and not exists(select 1 from public.ubicaciones u
    where u.id=p_ubicacion_destino_id and u.activo and u.permite_inventario and u.permite_venta) then
    raise exception 'La sucursal no está habilitada para inventario y venta'; end if;
  if p_ubicacion_destino_id is not null then
    select permite_recepcion and permite_transferencia into admite_traslados from public.ubicaciones where id=p_ubicacion_destino_id;
  end if;
  select greatest(1,coalesce(max_cantidad_por_linea,100)) into limite from public.configuracion_ecommerce where id=true;
  limite:=coalesce(limite,100);
  select coalesce(jsonb_agg(jsonb_build_object('id',u.id,'codigo',u.codigo,'nombre',u.nombre,
    'direccion',u.direccion,'permite_transferencia',u.permite_transferencia,'permite_recepcion',u.permite_recepcion) order by u.orden,u.codigo,u.id),'[]'::jsonb)
    into locales from public.ubicaciones u where u.activo and u.permite_inventario and u.permite_venta;
  with disponibles as (
    select e.producto_id,e.ubicacion_id,e.stock_disponible,u.codigo,u.nombre,u.orden
    from public.existencias e join public.ubicaciones u on u.id=e.ubicacion_id
    where e.activo and u.activo and u.permite_inventario
      and (u.id=p_ubicacion_destino_id or (admite_traslados and u.permite_transferencia))
  ), elegibles as (
    select p.id,p.sku,p.nombre,coalesce(sum(d.stock_disponible),0) stock_red,
      coalesce(sum(d.stock_disponible) filter(where d.ubicacion_id=p_ubicacion_destino_id),0) stock_local,
      coalesce(jsonb_agg(jsonb_build_object('ubicacion_id',d.ubicacion_id,'codigo',d.codigo,'nombre',d.nombre,'stock_disponible',d.stock_disponible) order by d.orden,d.codigo,d.ubicacion_id) filter(where d.ubicacion_id is not null),'[]'::jsonb) sucursales
    from public.productos p join public.categorias c on c.id=p.categoria_id
    left join public.marcas marca on marca.id=p.marca_id
    left join disponibles d on d.producto_id=p.id
    where p.activo and not p.descontinuado and p.es_vendible and p.es_comprable
      and p.controla_inventario and p.publicado_ecommerce and p.visible_ecommerce and c.activo and c.visible_ecommerce and (p.marca_id is null or marca.activo)
      and (p_producto_ids is null or p.id=any(p_producto_ids))
    group by p.id,p.sku,p.nombre order by p.nombre,p.id limit 1000
  )
  select coalesce(jsonb_agg(jsonb_build_object('producto_id',id,'nombre',nombre,'sku',sku,
    'stock_red',stock_red,'stock_local',stock_local,'stock_otras_sucursales',stock_red-stock_local,
    'cantidad_maxima',least(stock_red,limite),'sucursales',sucursales) order by nombre,id),'[]'::jsonb) into resultado from elegibles;
  return jsonb_build_object('productos',resultado,'sucursales',locales,'ubicacion_destino_id',p_ubicacion_destino_id);
end;
$function$

CREATE OR REPLACE FUNCTION erp_private.normalizar_lineas_presentaciones(p_items jsonb, p_limite integer DEFAULT 500)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE x jsonb; pid uuid; sid uuid; q numeric; result jsonb;
BEGIN
 IF p_items IS NULL OR jsonb_typeof(p_items)<>'array' OR jsonb_array_length(p_items) NOT BETWEEN 1 AND p_limite THEN
  RAISE EXCEPTION 'Cantidad de líneas inválida' USING ERRCODE='22023'; END IF;
 FOR x IN SELECT value FROM jsonb_array_elements(p_items) LOOP
  IF jsonb_typeof(x)<>'object' OR jsonb_typeof(x->'producto_id') IS DISTINCT FROM 'string'
   OR jsonb_typeof(x->'cantidad') IS DISTINCT FROM 'number'
   OR (x?'presentacion_id' AND x->'presentacion_id'<>'null'::jsonb AND jsonb_typeof(x->'presentacion_id')<>'string') THEN
   RAISE EXCEPTION 'Cada línea necesita producto, presentación opcional y cantidad numérica' USING ERRCODE='22023'; END IF;
  pid:=(x->>'producto_id')::uuid; sid:=(x->>'presentacion_id')::uuid; q:=(x->>'cantidad')::numeric;
  IF pid IS NULL OR q IS NULL OR q<=0 OR q>99999999999.999 OR q::text IN('NaN','Infinity','-Infinity') OR round(q,3)<>q
   OR (sid IS NOT NULL AND trunc(q)<>q) THEN
   RAISE EXCEPTION 'La cantidad debe ser positiva; las presentaciones se venden en paquetes enteros y la unidad base admite hasta tres decimales' USING ERRCODE='22023'; END IF;
  IF sid IS NULL AND EXISTS(SELECT 1 FROM public.productos p JOIN public.unidades_medida u ON u.id=p.unidad_medida_id
   WHERE p.id=pid AND (round(q,CASE WHEN p.venta_fraccionada AND u.permite_fraccion THEN least(3,greatest(0,u.decimales_permitidos)) ELSE 0 END)<>q)) THEN
   RAISE EXCEPTION 'Cada línea debe respetar la precisión de venta de la unidad antes de consolidarse' USING ERRCODE='22023'; END IF;
 END LOOP;
 SELECT jsonb_agg(jsonb_build_object('producto_id',producto_id,'presentacion_id',presentacion_id,'cantidad',trim_scale(cantidad)) ORDER BY producto_id,presentacion_id NULLS FIRST)
 INTO result FROM (SELECT producto_id,presentacion_id,sum(cantidad) cantidad
  FROM jsonb_to_recordset(p_items)x(producto_id uuid,presentacion_id uuid,cantidad numeric) GROUP BY producto_id,presentacion_id) q;
 IF EXISTS(SELECT 1 FROM jsonb_to_recordset(result)x(cantidad numeric) WHERE cantidad>99999999999.999) THEN
  RAISE EXCEPTION 'Cantidad acumulada fuera de rango' USING ERRCODE='22023'; END IF;
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION erp_private.resolver_linea_presentacion(p_producto_id uuid, p_presentacion_id uuid, p_cantidad numeric, p_canal text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE p public.productos%rowtype; s public.producto_presentaciones%rowtype; u public.unidades_medida%rowtype;
 factor numeric:=1; precio numeric; descuento numeric; base numeric;
BEGIN
 SELECT * INTO p FROM public.productos WHERE id=p_producto_id;
 SELECT * INTO u FROM public.unidades_medida WHERE id=p.unidad_medida_id;
 IF p.id IS NULL OR NOT p.activo OR p.descontinuado OR NOT p.es_vendible OR NOT p.controla_inventario OR u.id IS NULL OR NOT u.activo
  OR p_canal NOT IN('POS','ECOMMERCE') OR (p_canal='POS' AND NOT p.disponible_pos)
  OR (p_canal='ECOMMERCE' AND (NOT p.publicado_ecommerce OR NOT p.visible_ecommerce OR NOT p.es_comprable
   OR NOT EXISTS(SELECT 1 FROM public.categorias c WHERE c.id=p.categoria_id AND c.activo AND c.visible_ecommerce)
   OR (p.marca_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.marcas m WHERE m.id=p.marca_id AND m.activo)))) THEN
  RAISE EXCEPTION 'Producto no disponible para este canal' USING ERRCODE='22023'; END IF;
 precio:=p.precio_base;
 IF p_presentacion_id IS NOT NULL THEN
  SELECT * INTO s FROM public.producto_presentaciones WHERE id=p_presentacion_id AND producto_id=p.id;
  IF NOT FOUND OR NOT s.activo OR (p_canal='POS' AND NOT s.disponible_pos) OR (p_canal='ECOMMERCE' AND NOT s.disponible_ecommerce) THEN
   RAISE EXCEPTION 'La presentación ya no está disponible para este producto' USING ERRCODE='22023'; END IF;
  IF trunc(p_cantidad)<>p_cantidad THEN RAISE EXCEPTION 'Indica un número entero de presentaciones' USING ERRCODE='22023'; END IF;
  factor:=s.cantidad_base; precio:=s.precio;
 END IF;
 base:=p_cantidad*factor;
 IF p_cantidad IS NULL OR p_cantidad<=0 OR p_cantidad::text IN('NaN','Infinity','-Infinity') OR base>99999999999.999
  OR round(base,3)<>base OR (NOT(p.venta_fraccionada AND u.permite_fraccion) AND trunc(base)<>base) THEN
  RAISE EXCEPTION 'Cantidad incompatible con la unidad base del producto' USING ERRCODE='22023'; END IF;
 PERFORM erp_private.validar_cantidad_producto(p.id,base);
 IF precio IS NULL OR precio<0 OR precio::text IN('NaN','Infinity','-Infinity') THEN RAISE EXCEPTION 'Precio inválido'; END IF;
 SELECT max(oferta_porcentaje) INTO descuento FROM public.ofertas_producto WHERE producto_id=p.id AND activo
  AND ((p_canal='POS' AND aplica_pos) OR (p_canal='ECOMMERCE' AND aplica_ecommerce)) AND fecha_inicio<=now() AND (fecha_fin IS NULL OR fecha_fin>=now());
 IF descuento IS NOT NULL AND (descuento<0 OR descuento>100 OR descuento::text IN('NaN','Infinity','-Infinity')) THEN RAISE EXCEPTION 'Oferta inválida'; END IF;
 precio:=round(precio*(1-coalesce(descuento,0)/100),2);
 RETURN jsonb_build_object('producto_id',p.id,'presentacion_id',p_presentacion_id,'presentacion_nombre',s.nombre,
  'cantidad',p_cantidad,'cantidad_base',base,'factor',factor,'precio',precio,'total',round(p_cantidad*precio,2));
END $function$

CREATE OR REPLACE FUNCTION erp_private.validar_cantidad_producto(p_producto uuid, p_cantidad numeric, p_permitir_archivado boolean DEFAULT false)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE p public.productos%rowtype; u public.unidades_medida%rowtype; decimales integer;
BEGIN
 IF p_producto IS NULL OR p_cantidad IS NULL OR p_cantidad::text IN('NaN','Infinity','-Infinity')
   OR abs(p_cantidad)>=100000000000 OR round(p_cantidad,3)<>p_cantidad THEN
  RAISE EXCEPTION 'Cantidad inválida: número finito, menor a 100 mil millones y máximo 3 decimales' USING ERRCODE='22023'; END IF;
 SELECT * INTO p FROM public.productos WHERE id=p_producto FOR NO KEY UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Producto no encontrado' USING ERRCODE='22023'; END IF;
 SELECT * INTO u FROM public.unidades_medida WHERE id=p.unidad_medida_id FOR SHARE;
 IF NOT FOUND OR (NOT coalesce(p_permitir_archivado,false) AND (NOT p.activo OR NOT p.controla_inventario OR NOT u.activo)) THEN
  RAISE EXCEPTION 'Producto o unidad no habilitados para inventario' USING ERRCODE='22023'; END IF;
 decimales:=CASE WHEN u.permite_fraccion THEN least(3,greatest(0,u.decimales_permitidos)) ELSE 0 END;
 IF round(p_cantidad,decimales)<>p_cantidad THEN
  RAISE EXCEPTION 'Cantidad incompatible con unidad %: admite % decimales',u.abreviatura,decimales USING ERRCODE='22023'; END IF;
END; $function$

CREATE OR REPLACE FUNCTION public.validar_disponibilidad_presentaciones(p_items jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE lines jsonb; line record; resolved jsonb; sums jsonb:='{}'::jsonb; result jsonb:='[]'::jsonb; k text; available numeric; wanted numeric; configured uuid;
BEGIN
 lines:=erp_private.normalizar_lineas_presentaciones(p_items,100);
 SELECT ubicacion_ecommerce_id INTO configured FROM public.configuracion_ecommerce WHERE id=true;
 FOR line IN SELECT * FROM jsonb_to_recordset(lines)x(producto_id uuid,presentacion_id uuid,cantidad numeric) LOOP
  BEGIN
   resolved:=erp_private.resolver_linea_presentacion(line.producto_id,line.presentacion_id,line.cantidad,'ECOMMERCE');
   k:=line.producto_id::text;
   sums:=jsonb_set(sums,ARRAY[k],to_jsonb(coalesce((sums->>k)::numeric,0)+(resolved->>'cantidad_base')::numeric));
  EXCEPTION WHEN raise_exception OR invalid_parameter_value THEN
   result:=result||jsonb_build_array(jsonb_build_object('producto_id',line.producto_id,'estado','NO_DISPONIBLE','mensaje','El producto o presentación ya no está disponible; revisa el carrito'));
  END;
 END LOOP;
 FOR k,wanted IN SELECT key,value::text::numeric FROM jsonb_each(sums) LOOP
  SELECT coalesce(sum(e.stock_disponible),0) INTO available FROM public.existencias e JOIN public.ubicaciones u ON u.id=e.ubicacion_id
   WHERE e.producto_id=k::uuid AND e.ubicacion_id=configured AND e.activo AND u.activo AND u.permite_inventario AND u.permite_venta;
  result:=result||jsonb_build_array(jsonb_build_object('producto_id',k,'estado',CASE WHEN available>=wanted THEN 'DISPONIBLE' ELSE 'AGOTADO' END,
   'mensaje',CASE WHEN available>=wanted THEN 'Cantidad disponible en la sucursal de la tienda; se confirma al finalizar' ELSE 'No hay disponibilidad para todas las presentaciones seleccionadas' END));
 END LOOP;
 RETURN result;
END $function$
